import{_ as n,o as a,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"map、geo 与 split_clients","description":"map 的匹配优先级与惰性求值、geo 的 CIDR 查表、split_clients 做灰度发布。","frontmatter":{"title":"map、geo 与 split_clients","description":"map 的匹配优先级与惰性求值、geo 的 CIDR 查表、split_clients 做灰度发布。","source":"https://daiw.org/manual/nginx/map-geo"},"headers":[],"relativePath":"manual/tools/nginx/map-geo.md","filePath":"manual/tools/nginx/map-geo.md"}'),l={name:"manual/tools/nginx/map-geo.md"};function t(i,s,r,o,c,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="map、geo-与-split-clients" tabindex="-1">map、geo 与 split_clients <a class="header-anchor" href="#map、geo-与-split-clients" aria-label="Permalink to &quot;map、geo 与 split_clients&quot;">​</a></h1><p>这三个模块都在 <code>http</code> 上下文定义变量，是替代 <a href="/Front2Full/manual/tools/nginx/rewrite"><code>if</code></a> 的正确工具。</p><h2 id="map" tabindex="-1">map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;map&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    map string $variable { ... }</span></span>
<span class="line"><span>上下文:  http</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $http_user_agent $is_bot {</span></span>
<span class="line"><span>    default            0;</span></span>
<span class="line"><span>    ~*(bot|spider)     1;</span></span>
<span class="line"><span>    &quot;Googlebot/2.1&quot;    1;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>根据一个变量的值，计算出另一个变量。</strong></p><h3 id="匹配优先级" tabindex="-1">匹配优先级 <a class="header-anchor" href="#匹配优先级" aria-label="Permalink to &quot;匹配优先级&quot;">​</a></h3><p>nginx 按这个顺序找：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 精确字符串</span></span>
<span class="line"><span>2. 最长的【前缀】通配（&quot;*.example.com&quot; 形式，以 * 开头）</span></span>
<span class="line"><span>3. 最长的【后缀】通配（&quot;www.*&quot; 形式，以 * 结尾）</span></span>
<span class="line"><span>4. 第一个匹配的正则（按配置顺序）</span></span>
<span class="line"><span>5. default</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>与 <a href="/Front2Full/manual/tools/nginx/request-processing"><code>server_name</code> 的规则</a>同构——<strong>精确优先、通配比长度、正则比顺序</strong>。</p><h3 id="特殊参数" tabindex="-1">特殊参数 <a class="header-anchor" href="#特殊参数" aria-label="Permalink to &quot;特殊参数&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $uri $value {</span></span>
<span class="line"><span>    hostnames;              # 按主机名规则匹配（支持 *.example.com）</span></span>
<span class="line"><span>    volatile;               # 禁用缓存，每次重新求值</span></span>
<span class="line"><span>    default    &quot;none&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    include    /etc/nginx/map-values.conf;   # 可以 include</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /foo       &quot;A&quot;;</span></span>
<span class="line"><span>    ~^/bar/    &quot;B&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>default</code></td><td>无匹配时的值。<strong>不写则为空串</strong></td></tr><tr><td><code>hostnames</code></td><td>按主机名规则匹配（允许 <code>*.</code> 前缀通配）</td></tr><tr><td><code>volatile</code></td><td><strong>禁用结果缓存</strong></td></tr><tr><td><code>include</code></td><td>从文件读映射表——大表必备</td></tr></tbody></table><h3 id="惰性求值与缓存" tabindex="-1">惰性求值与缓存 <a class="header-anchor" href="#惰性求值与缓存" aria-label="Permalink to &quot;惰性求值与缓存&quot;">​</a></h3><p><strong><code>map</code> 定义的变量在首次被使用时才计算，且结果会缓存到请求结束。</strong></p><p>两个推论：</p><ul><li>定义 100 个 map 但只用到 1 个，另外 99 个<strong>完全不消耗</strong>。可以放心大量定义。</li><li>若映射依赖的源变量在请求中途会变（比如 <code>$uri</code> 被 <a href="/Front2Full/manual/tools/nginx/rewrite">rewrite 改写</a>），缓存的结果<strong>不会更新</strong>——此时需要 <code>volatile</code>。</li></ul><h3 id="值可以是变量" tabindex="-1">值可以是变量 <a class="header-anchor" href="#值可以是变量" aria-label="Permalink to &quot;值可以是变量&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $http_x_env $backend {</span></span>
<span class="line"><span>    default  &quot;prod_pool&quot;;</span></span>
<span class="line"><span>    &quot;staging&quot; &quot;staging_pool&quot;;</span></span>
<span class="line"><span>    &quot;canary&quot;  &quot;canary_pool&quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location / {</span></span>
<span class="line"><span>    proxy_pass http://$backend;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong><code>proxy_pass</code> 里含变量时行为不同</strong>（<a href="/Front2Full/manual/tools/nginx/proxy">见代理章节</a>）：nginx 不会在启动时解析上游组，而是运行时解析——若值是域名则需要 <code>resolver</code>，若是 upstream 名则需确保该组已定义。</p><h3 id="典型用途" tabindex="-1">典型用途 <a class="header-anchor" href="#典型用途" aria-label="Permalink to &quot;典型用途&quot;">​</a></h3><p><strong>替代 if 做条件判断：</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $request_method $not_allowed {</span></span>
<span class="line"><span>    default 0;</span></span>
<span class="line"><span>    TRACE   1;</span></span>
<span class="line"><span>    TRACK   1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    if ($not_allowed) { return 405; }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>按类型设缓存时长</strong>（官方示例）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $sent_http_content_type $expires {</span></span>
<span class="line"><span>    default         off;</span></span>
<span class="line"><span>    application/pdf 42d;</span></span>
<span class="line"><span>    ~image/         max;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>expires $expires;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>条件日志：</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $status $loggable {</span></span>
<span class="line"><span>    ~^[23]  0;</span></span>
<span class="line"><span>    default 1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>access_log /var/log/nginx/access.log main if=$loggable;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>WebSocket 升级</strong>（最经典的 map 用法）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $http_upgrade $connection_upgrade {</span></span>
<span class="line"><span>    default upgrade;</span></span>
<span class="line"><span>    &#39;&#39;      close;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location /ws/ {</span></span>
<span class="line"><span>    proxy_pass http://backend;</span></span>
<span class="line"><span>    proxy_http_version 1.1;</span></span>
<span class="line"><span>    proxy_set_header Upgrade    $http_upgrade;</span></span>
<span class="line"><span>    proxy_set_header Connection $connection_upgrade;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>这里必须用 map 而不是硬写 <code>Connection upgrade</code>——<a href="https://daiw.org/manual/http11/connection-management" target="_blank" rel="noreferrer">非 WebSocket 请求也走这个 location 时</a>，发 <code>Connection: upgrade</code> 会破坏普通请求。</p><h2 id="geo" tabindex="-1">geo <a class="header-anchor" href="#geo" aria-label="Permalink to &quot;geo&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    geo [$address] $variable { ... }</span></span>
<span class="line"><span>上下文:  http</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>geo $country {</span></span>
<span class="line"><span>    default        unknown;</span></span>
<span class="line"><span>    127.0.0.1/32   local;</span></span>
<span class="line"><span>    10.0.0.0/8     internal;</span></span>
<span class="line"><span>    192.168.0.0/16 internal;</span></span>
<span class="line"><span>    203.0.113.0/24 partner;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>按 IP 地址（CIDR）查表</strong>，默认用 <code>$remote_addr</code>，可以指定其他变量：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>geo $http_x_forwarded_for $from_trusted { ... }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>default</code></td><td>无匹配时的值</td></tr><tr><td><code>ranges</code></td><td>用<strong>地址区间</strong>而非 CIDR，且必须是第一条</td></tr><tr><td><code>delete</code></td><td>删除指定网络</td></tr><tr><td><code>proxy</code></td><td>指定可信代理，从 <code>X-Forwarded-For</code> 取地址</td></tr><tr><td><code>proxy_recursive</code></td><td>递归查找</td></tr><tr><td><code>include</code></td><td>从文件读——<strong>IP 库必备</strong></td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>geo $country {</span></span>
<span class="line"><span>    ranges;</span></span>
<span class="line"><span>    default            unknown;</span></span>
<span class="line"><span>    203.0.113.0-203.0.113.255  partner;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="与-map-的分工" tabindex="-1">与 map 的分工 <a class="header-anchor" href="#与-map-的分工" aria-label="Permalink to &quot;与 map 的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><code>map</code></th><th><code>geo</code></th></tr></thead><tbody><tr><td>输入</td><td>任意变量</td><td><strong>IP 地址</strong></td></tr><tr><td>匹配</td><td>字符串/通配/正则</td><td><strong>CIDR / 区间</strong></td></tr><tr><td>数据结构</td><td>哈希表</td><td><strong>基数树（radix tree）</strong></td></tr></tbody></table><p><code>geo</code> 用基数树做最长前缀匹配，<strong>几十万条 CIDR 也是 O(位数)</strong>。用 <code>map</code> 硬匹配 IP 字符串既不正确（无法处理网段）也不高效。</p><p>典型用途：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>geo $limit_key {</span></span>
<span class="line"><span>    default        $binary_remote_addr;</span></span>
<span class="line"><span>    10.0.0.0/8     &quot;&quot;;              # 内网不限流（key 为空则不计入）</span></span>
<span class="line"><span>    192.168.0.0/16 &quot;&quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>limit_req_zone $limit_key zone=one:10m rate=10r/s;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><a href="/Front2Full/manual/tools/nginx/access-limits">限流</a>时把内网排除——key 为空串的请求不参与限流。</p><h2 id="split-clients" tabindex="-1">split_clients <a class="header-anchor" href="#split-clients" aria-label="Permalink to &quot;split\\_clients&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    split_clients string $variable { ... }</span></span>
<span class="line"><span>上下文:  http</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>split_clients &quot;\${remote_addr}\${http_user_agent}&quot; $variant {</span></span>
<span class="line"><span>    5%      &quot;canary&quot;;</span></span>
<span class="line"><span>    20%     &quot;beta&quot;;</span></span>
<span class="line"><span>    *       &quot;stable&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>按比例把请求分流</strong>——A/B 测试与灰度发布的标准工具。</p><p>工作原理：对输入字符串算 MurmurHash2，把 32 位哈希空间按百分比切分。</p><p>要点：</p><ul><li><strong><code>*</code> 表示剩余全部</strong>，必须有（否则未覆盖部分变量为空）。</li><li><strong>同一个输入永远落到同一个分组</strong>——哈希是确定性的。所以用 <code>$remote_addr</code> 做 key 时，同一用户始终看到同一版本（会话一致性）。</li><li>想让每个请求随机分配，用 <code>$request_id</code>（1.11.0+）：</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>split_clients $request_id $variant {</span></span>
<span class="line"><span>    50%  &quot;a&quot;;</span></span>
<span class="line"><span>    *    &quot;b&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="灰度发布" tabindex="-1">灰度发布 <a class="header-anchor" href="#灰度发布" aria-label="Permalink to &quot;灰度发布&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>split_clients &quot;\${remote_addr}&quot; $pool {</span></span>
<span class="line"><span>    10%  &quot;backend_v2&quot;;</span></span>
<span class="line"><span>    *    &quot;backend_v1&quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>upstream backend_v1 { server 10.0.1.10:8080; }</span></span>
<span class="line"><span>upstream backend_v2 { server 10.0.2.10:8080; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        proxy_pass http://$pool;</span></span>
<span class="line"><span>        add_header X-Pool $pool always;   # 便于验证</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>配合 map 做<strong>手动覆盖</strong>（让测试人员强制走新版）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $cookie_force_pool $forced {</span></span>
<span class="line"><span>    default  &quot;&quot;;</span></span>
<span class="line"><span>    &quot;v2&quot;     &quot;backend_v2&quot;;</span></span>
<span class="line"><span>    &quot;v1&quot;     &quot;backend_v1&quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>map $forced $final_pool {</span></span>
<span class="line"><span>    default  $forced;      # Cookie 指定了就用它</span></span>
<span class="line"><span>    &quot;&quot;       $pool;        # 否则用 split_clients 的结果</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><strong>map 可以链式引用另一个 map 的结果</strong>——这是构建复杂路由逻辑的正确方式，比嵌套 <code>if</code> 清晰得多。</p><h2 id="三者对照" tabindex="-1">三者对照 <a class="header-anchor" href="#三者对照" aria-label="Permalink to &quot;三者对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>map</code></th><th><code>geo</code></th><th><code>split_clients</code></th></tr></thead><tbody><tr><td>输入</td><td>任意变量</td><td>IP</td><td>任意字符串</td></tr><tr><td>输出</td><td>查表结果</td><td>查表结果</td><td><strong>按比例分组</strong></td></tr><tr><td>匹配</td><td>精确/通配/正则</td><td>CIDR</td><td>哈希取模</td></tr><tr><td>上下文</td><td><code>http</code></td><td><code>http</code></td><td><code>http</code></td></tr><tr><td>典型用途</td><td>条件逻辑、替代 if</td><td>IP 白名单、地域</td><td>灰度、A/B</td></tr></tbody></table><p>三者都<strong>只定义变量、不产生副作用</strong>，且都是惰性求值——这正是它们优于 <code>if</code> 的根本原因。</p><p>下一篇：<a href="/Front2Full/manual/tools/nginx/stream">stream：TCP/UDP 代理</a>。</p>`,61)])])}const m=n(l,[["render",t]]);export{u as __pageData,m as default};
